# Cleanup candidates from the R16 load harness (spec 012, docs/plans/2026-08-29-005).
#
# Bare invocation is the dry run. -Execute (-e) is the only way to act. Nothing here is
# irreversible, so no second flag: every path below is regenerated by the next
# `deno run -A tools/bench/run.ts`.
#
# NOT removed, and not by asking either: tools/bench/baseline.json (the committed measurement
# R16 rests on), the feat/012-bench-harness branch, and apps/web's publish output, which is
# every test tier's launch target and not this work's to delete.
[CmdletBinding()]
param(
    [Alias('e')][switch]$Execute
)

$ErrorActionPreference = 'Stop'
$repo = Split-Path -Parent (Split-Path -Parent $PSScriptRoot)

$candidates = @(
    @{ Path = Join-Path $repo 'tmp\bench'; What = 'harness scratch: latest.json plus the throwaway CA, leaf and key' }
    @{ Path = Join-Path $repo 'tmp\bench-probe.ts'; What = 'the probe that found the GET / 500 over http' }
    @{ Path = Join-Path $repo 'tmp\baseline-real.json'; What = 'baseline copy kept while the regression path was verified' }
    @{ Path = Join-Path $repo 'tmp\bench-probe.log'; What = 'probe output' }
    @{ Path = Join-Path $repo 'tmp\012-bench-branch.diff'; What = 'branch diff handed to the code review' }
)

# The test suite's scratch directories, one per run, named by tools/bench/scratch.ts. Globbed
# rather than listed: a killed run leaves one behind and the count is not knowable in advance.
$candidates += @(
    Get-ChildItem -Path (Join-Path $repo 'tmp') -Directory -Filter 'bench-test-*' -ErrorAction SilentlyContinue |
        ForEach-Object { @{ Path = $_.FullName; What = 'test scratch left by a killed deno test run' } }
)

$found = @($candidates | Where-Object { Test-Path $_.Path })

if ($found.Count -eq 0) {
    Write-Host 'Nothing to remove.'
    return
}

foreach ($item in $found) {
    $size = (Get-ChildItem -LiteralPath $item.Path -Recurse -File -ErrorAction SilentlyContinue |
        Measure-Object -Property Length -Sum).Sum
    if ($null -eq $size) { $size = (Get-Item -LiteralPath $item.Path).Length }
    Write-Host ("{0}  ({1:N0} bytes) -- {2}" -f $item.Path, $size, $item.What)
}

if (-not $Execute) {
    Write-Host ''
    Write-Host ("Dry run. {0} item(s) listed. Re-run with -Execute to remove them." -f $found.Count)
    return
}

foreach ($item in $found) {
    Remove-Item -LiteralPath $item.Path -Recurse -Force
    Write-Host ("Removed {0}" -f $item.Path)
}
